class vector3d
{
public:
    float x;
    float y;
    float z;
};

class po
{
public:
    vector3d slow_xform(const vector3d &value) const;
};

class color32
{
public:
    unsigned int value;
};

typedef unsigned short vert_ref;
typedef unsigned short material_ref;

class cface
{
public:
    vert_ref get_vert_ref(int index) const { return vert_refs[index]; }

private:
    vert_ref vert_refs[3];
    material_ref my_material;
    vector3d raw_normal;
    vector3d normal __attribute__((aligned(16)));
    vector3d raw_center;
    vector3d center;
    float radius;
    unsigned short flags;
};

class vert
{
public:
    const vector3d &get_point() const { return point; }

    vector3d point __attribute__((aligned(16)));
    int num_bones;
    unsigned char bone_ids[4];
    float bone_weights[4];
};

template <class T>
class vector
{
public:
    class const_iterator
    {
    public:
        const_iterator(const T *value) : current(value) {}
        const T &operator*() const { return *current; }
        const_iterator &operator++() { ++current; return *this; }
        bool operator!=(const const_iterator &other) const
        {
            return current != other.current;
        }

    private:
        const T *current;
    };

    const_iterator begin() const { return const_iterator(start); }
    const_iterator end() const { return const_iterator(finish); }

private:
    T *start;
    T *finish;
    T *storage_end;
};

class collision_geometry
{
public:
    virtual ~collision_geometry();

protected:
    void *owner;
    bool valid;
};

class cg_mesh : public collision_geometry
{
public:
    const vert &get_raw_vert(vert_ref index) const { return raw_verts[index]; }
    const vector<cface> &get_cfaces() const { return cfaces; }

protected:
    vector<vert> raw_verts;
    vector<vert> verts;
    vector<cface> cfaces;
};

void render_triangle(
    const vector3d &point1,
    const vector3d &point2,
    const vector3d &point3,
    color32 color,
    bool double_sided = false);

__asm__(".equ slow_xform__C2poRC8vector3d, 0x003482F8");
__asm__(".equ render_triangle__FRC8vector3dN20G7color32b, 0x002C80E0");

static void render_cgmesh(const cg_mesh *colgeom, const po &my_po, color32 col)
{
    for (vector<cface>::const_iterator i = colgeom->get_cfaces().begin();
         i != colgeom->get_cfaces().end();
         ++i)
    {
        render_triangle(my_po.slow_xform(colgeom->get_raw_vert((*i).get_vert_ref(0)).get_point()),
                        my_po.slow_xform(colgeom->get_raw_vert((*i).get_vert_ref(1)).get_point()),
                        my_po.slow_xform(colgeom->get_raw_vert((*i).get_vert_ref(2)).get_point()),
                        col);
    }
}
